export type GovernancePluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function governanceProgram() {
  return <T extends GovernancePluginRequirements>(
    client: T,
  ): ExtendedClient<T, { governance: GovernancePlugin }> => {
    return extendClient(client, {
      governance: <GovernancePlugin>{
        accounts: {
          governor: addSelfFetchFunctions(client, getGovernorCodec()),
          proposal: addSelfFetchFunctions(client, getProposalCodec()),
          proposalMeta: addSelfFetchFunctions(client, getProposalMetaCodec()),
          optionProposalMeta: addSelfFetchFunctions(
            client,
            getOptionProposalMetaCodec(),
          ),
          vote: addSelfFetchFunctions(client, getVoteCodec()),
        },
        instructions: {
          createGovernor: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateGovernorInstruction({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          createProposal: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateProposalInstruction({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          activateProposal: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getActivateProposalInstruction(input),
            ),
          cancelProposal: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCancelProposalInstruction(input),
            ),
          queueProposal: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getQueueProposalInstruction({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          newVote: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getNewVoteInstruction({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          setVote: (input) =>
            addSelfPlanAndSendFunctions(client, getSetVoteInstruction(input)),
          setGovernanceParams: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetGovernanceParamsInstruction(input),
            ),
          setVotingReward: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetVotingRewardInstruction(input),
            ),
          claimReward: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimRewardInstruction(input),
            ),
          setLocker: (input) =>
            addSelfPlanAndSendFunctions(client, getSetLockerInstruction(input)),
          createProposalMeta: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateProposalMetaInstruction({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          createOptionProposalMeta: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateOptionProposalMetaInstruction({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
        },
        identifyAccount: identifyGovernanceAccount,
        identifyInstruction: identifyGovernanceInstruction,
        parseInstruction: parseGovernanceInstruction,
      },
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
